#include "stdlib/math/base/special/binetf.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/powf.h"
#include "stdlib/math/base/special/expf.h"
#include "stdlib/math/base/special/lnf.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/special/cospif.h"
#include "stdlib/constants/float32/phi.h"
#include "stdlib/constants/float32/pinf.h"
#include "stdlib/constants/float32/ninf.h"
#include "stdlib/constants/float32/nan.h"

static const float SQRT_5 = 2.23606797749979f;
static const float LN_PHI = 0.48121182505960347f;
static const float LN_SQRT_5 = 0.80471895621705014f;
static const float OVERFLOW_THRESHOLD = 184.37377929687500f;

/**
* Evaluates Binet's formula extended to real numbers for a single-precision floating-point number.
*
* ## Method
*
* Binet's formula is
*
* ```tex
* \operatorname{binet}(x) = \frac{\varphi^x - \cos(\pi x)\,\varphi^{-x}}{\sqrt{5}}
* ```
*
* In single-precision floating-point arithmetic, directly evaluating \\( \varphi^x \\) overflows once \\( x \\) exceeds the natural logarithm of the maximum single-precision floating-point number divided by \\( \ln(\varphi) \\), even though the function value \\( \varphi^x / \sqrt{5} \\) remains representable for \\( x < \bigl(\ln(\mathtt{FLT\_MAX}) + \tfrac{1}{2}\ln(5)\bigr) / \ln(\varphi) \\). We therefore factor out the dominant term. For \\( x \ge 0 \\),
*
* ```tex
* \operatorname{binet}(x) = \frac{\varphi^{|x|}}{\sqrt{5}} - \cos(\pi x)\,\frac{\varphi^{-|x|}}{\sqrt{5}}
* ```
*
* and for \\( x < 0 \\),
*
* ```tex
* \operatorname{binet}(x) = \frac{\varphi^{-|x|}}{\sqrt{5}} - \cos(\pi x)\,\frac{\varphi^{|x|}}{\sqrt{5}}.
* ```
*
* When the dominant term would overflow, it is evaluated in log space. For negative \\( x \\), the magnitude of the dominant term is \\( |\cos(\pi x)| \cdot \varphi^{|x|} / \sqrt{5} \\), so we fold \\( \ln|\cos(\pi x)| \\) into the exponent in order to preserve finiteness of results which are representable in single precision:
*
* ```tex
* \frac{|\cos(\pi x)| \cdot \varphi^{|x|}}{\sqrt{5}} = \exp\Bigl( |x|\,\ln(\varphi) + \ln|\cos(\pi x)| - \tfrac{1}{2}\ln(5) \Bigr).
* ```
*
* Note that the cancellation of the two terms of Binet's formula near \\( x = 0 \\) (and, for negative \\( x \\), near the negative half-integers) is inherent to the formula itself and limits _relative_ accuracy; _absolute_ accuracy is unaffected.
*
* @param x    input value
* @return     real-valued result
*
* @example
* float y = stdlib_base_binetf( 2.0 );
* // returns 1.0
*/
float stdlib_base_binetf( const float x ) {
	float a;
	float b;
	float c;
	float ax;
	float eps;
	float dom;

	if ( stdlib_base_is_nanf( x ) || x == STDLIB_CONSTANT_FLOAT32_PINF || x == STDLIB_CONSTANT_FLOAT32_NINF ) {
		return STDLIB_CONSTANT_FLOAT32_NAN;
	}
	ax = stdlib_base_absf( x );
	if ( ax < OVERFLOW_THRESHOLD ) {
		a = stdlib_base_powf( STDLIB_CONSTANT_FLOAT32_PHI, x );
		b = stdlib_base_cospif( x ) / a;
		return ( a - b ) / SQRT_5;
	}
	// `|x|` is large enough that `powf( PHI, x )` (or `cospi(x)/powf(PHI,x)`) would overflow: evaluate the dominant term in log space
	eps = stdlib_base_expf( ( -ax*LN_PHI ) - LN_SQRT_5 ); // φ^(-|x|)/√5
	if ( x > 0.0f ) {
		// dominant term is φ^x/√5; the second term of Binet's formula is below single-precision resolution
		return stdlib_base_expf( ( ax*LN_PHI ) - LN_SQRT_5 );
	}
	// dominant term is -cos(πx)·φ^(-x)/√5; fold ln|cos(πx)| into the exponent to preserve finiteness (note: `stdlib_base_lnf( 0.0f )` is `-infinity`, so exact half-integers naturally return `eps`)
	c = stdlib_base_cospif( x );
	dom = stdlib_base_expf( ( ( ax*LN_PHI ) + stdlib_base_lnf( stdlib_base_absf( c ) ) ) - LN_SQRT_5 );
	if ( c > 0.0f ) {
		return eps - dom;
	}
	return eps + dom;
}
